28:
29:/** Resolves inherited cockpit roles with deny precedence and zone constraints. */
30:public final class RoleAuthorizationGraph {
31:    public enum Effect {
32:        ALLOW,
33:        DENY
34:    }
35:
36:    public static final class Permission {
37:        public final String operation;
38:        public final Effect effect;
39:        public final Set<String> zones;
40:        public final boolean recentAuthenticationRequired;
41:
42:        public Permission(
43:                String operation,
44:                Effect effect,
45:                Collection<String> zones,
46:                boolean recentAuthenticationRequired) {
47:            this.operation = require(operation, "operation");
48:            this.effect = Objects.requireNonNull(effect, "effect");
49:            this.zones = immutableSet(zones);
50:            this.recentAuthenticationRequired = recentAuthenticationRequired;
51:            if (this.zones.isEmpty()) {
52:                throw new IllegalArgumentException("permission needs a zone");
53:            }
54:        }
55:    }
56:
57:    public static final class Role {
58:        public final String id;
59:        public final Set<String> parents;
60:        public final List<Permission> permissions;
61:        public final boolean assignable;
62:
63:        public Role(
64:                String id,
65:                Collection<String> parents,
66:                Collection<Permission> permissions,
67:                boolean assignable) {
68:            this.id = require(id, "id");
69:            this.parents = immutableSet(parents);
70:            this.permissions = Collections.unmodifiableList(
71:                    new ArrayList<>(Objects.requireNonNull(permissions, "permissions")));
72:            this.assignable = assignable;
73:            if (this.parents.contains(id)) {
74:                throw new IllegalArgumentException("role cannot inherit itself");
75:            }
76:        }
77:    }
78:
79:    public static final class Assignment {
80:        public final String roleId;
81:        public final String zone;
82:        public final long validFrom;
83:        public final long validUntil;
84:        public final String source;
85:
86:        public Assignment(
87:                String roleId,
88:                String zone,
89:                long validFrom,
90:                long validUntil,
91:                String source) {
92:            this.roleId = require(roleId, "roleId");
93:            this.zone = require(zone, "zone");
94:            this.validFrom = validFrom;
95:            this.validUntil = validUntil;
96:            this.source = require(source, "source");
97:            if (validFrom < 0 || validUntil <= validFrom) {
98:                throw new IllegalArgumentException("invalid assignment interval");
99:            }
100:        }
101:    }
102:
103:    public static final class Trace {
104:        public final String roleId;
105:        public final String operation;
106:        public final Effect effect;
107:        public final boolean zoneMatched;
108:        public final boolean authenticationSatisfied;
109:
110:        Trace(
111:                String roleId,
112:                String operation,
113:                Effect effect,
114:                boolean zoneMatched,
115:                boolean authenticationSatisfied) {
116:            this.roleId = roleId;
117:            this.operation = operation;
118:            this.effect = effect;
119:            this.zoneMatched = zoneMatched;
120:            this.authenticationSatisfied = authenticationSatisfied;
121:        }
122:    }
123:
124:    public static final class Decision {
125:        public final boolean allowed;
126:        public final boolean reauthenticationRequired;
127:        public final String reason;
128:        public final List<String> effectiveRoles;
129:        public final List<Trace> trace;
130:
131:        Decision(
132:                boolean allowed,
133:                boolean reauthenticationRequired,
134:                String reason,
135:                List<String> effectiveRoles,
136:                List<Trace> trace) {
137:            this.allowed = allowed;
138:            this.reauthenticationRequired = reauthenticationRequired;
139:            this.reason = reason;
140:            this.effectiveRoles = Collections.unmodifiableList(
141:                    new ArrayList<>(effectiveRoles));
142:            this.trace = Collections.unmodifiableList(new ArrayList<>(trace));
143:        }
144:    }
145:
146:    private final Map<String, Role> roles;
147:
148:    public RoleAuthorizationGraph(Collection<Role> roles) {
149:        Map<String, Role> indexed = new LinkedHashMap<>();
150:        for (Role role : Objects.requireNonNull(roles, "roles")) {
151:            if (indexed.put(role.id, role) != null) {
152:                throw new IllegalArgumentException("duplicate role: " + role.id);
153:            }
154:        }
155:        validateParents(indexed);
156:        validateAcyclic(indexed);
157:        this.roles = Collections.unmodifiableMap(indexed);
158:    }
159:
160:    public Decision authorize(
161:            Collection<Assignment> assignments,
162:            String operation,
163:            String zone,
164:            boolean recentlyAuthenticated,
165:            long now) {
166:        String requestedOperation = require(operation, "operation");
167:        String requestedZone = require(zone, "zone");
168:        Set<String> active = new LinkedHashSet<>();
169:        for (Assignment assignment : Objects.requireNonNull(assignments, "assignments")) {
170:            Role role = roles.get(assignment.roleId);
171:            if (role == null || !role.assignable) {
172:                continue;
173:            }
174:            if (assignment.validFrom <= now && assignment.validUntil > now
175:                    && zoneMatches(assignment.zone, requestedZone)) {
176:                collectRole(assignment.roleId, active);
177:            }
178:        }
179:        List<String> orderedRoles = new ArrayList<>(active);
180:        Collections.sort(orderedRoles);
181:        List<Trace> trace = new ArrayList<>();
182:        boolean allowed = false;
183:        boolean reauthenticationRequired = false;
184:        for (String roleId : orderedRoles) {
185:            Role role = roles.get(roleId);
186:            for (Permission permission : role.permissions) {
187:                if (!permission.operation.equals(requestedOperation)
188:                        && !permission.operation.equals("*")) {
189:                    continue;
190:                }
191:                boolean zoneMatched = permission.zones.contains("all")
192:                        || permission.zones.contains(requestedZone);
193:                boolean authenticationSatisfied = !permission.recentAuthenticationRequired
194:                        || recentlyAuthenticated;
195:                trace.add(new Trace(
196:                        roleId,
197:                        permission.operation,
198:                        permission.effect,
199:                        zoneMatched,
200:                        authenticationSatisfied));
201:                if (!zoneMatched) {
202:                    continue;
203:                }
204:                if (permission.effect == Effect.DENY) {
205:                    return new Decision(
206:                            false,
207:                            false,
208:                            "explicit deny from " + roleId,
209:                            orderedRoles,
210:                            trace);
211:                }
212:                if (!authenticationSatisfied) {
213:                    reauthenticationRequired = true;
214:                    continue;
215:                }
216:                allowed = true;
217:            }
218:        }
219:        if (allowed) {
220:            return new Decision(true, false, "allowed by effective role", orderedRoles, trace);
221:        }
222:        if (reauthenticationRequired) {
223:            return new Decision(
224:                    false,
225:                    true,
226:                    "recent authentication required",
227:                    orderedRoles,
228:                    trace);
229:        }
230:        return new Decision(false, false, "no matching grant", orderedRoles, trace);
231:    }
232:
233:    public List<String> inheritanceOrder(String roleId) {
234:        if (!roles.containsKey(roleId)) {
235:            throw new IllegalArgumentException("unknown role: " + roleId);
236:        }
237:        Set<String> collected = new LinkedHashSet<>();
238:        collectRole(roleId, collected);
239:        List<String> result = new ArrayList<>(collected);
240:        Collections.reverse(result);
241:        return Collections.unmodifiableList(result);
242:    }
243:
244:    public Map<String, List<String>> describeGraph() {
245:        Map<String, List<String>> result = new LinkedHashMap<>();
246:        List<String> ids = new ArrayList<>(roles.keySet());
247:        Collections.sort(ids);
248:        for (String id : ids) {
249:            List<String> parents = new ArrayList<>(roles.get(id).parents);
250:            Collections.sort(parents);
251:            result.put(id, Collections.unmodifiableList(parents));
252:        }
253:        return Collections.unmodifiableMap(result);
254:    }
255:
256:    private void collectRole(String roleId, Set<String> collected) {
257:        if (!collected.add(roleId)) {
258:            return;
259:        }
260:        List<String> parents = new ArrayList<>(roles.get(roleId).parents);
261:        Collections.sort(parents);
262:        for (String parent : parents) {
263:            collectRole(parent, collected);
264:        }
265:    }
266:
267:    private static boolean zoneMatches(String assignmentZone, String requestedZone) {
268:        return assignmentZone.equals("all") || assignmentZone.equals(requestedZone);
269:    }
270:
271:    private static void validateParents(Map<String, Role> roles) {
272:        for (Role role : roles.values()) {
273:            for (String parent : role.parents) {
274:                if (!roles.containsKey(parent)) {
275:                    throw new IllegalArgumentException(
276:                            "unknown parent " + parent + " for " + role.id);
277:                }
278:            }
279:        }
280:    }
281:
282:    private static void validateAcyclic(Map<String, Role> roles) {
283:        Set<String> visited = new LinkedHashSet<>();
284:        Set<String> visiting = new LinkedHashSet<>();
285:        for (String roleId : roles.keySet()) {
286:            visit(roleId, roles, visiting, visited);
287:        }
288:    }
289:
290:    private static void visit(
291:            String roleId,
292:            Map<String, Role> roles,
293:            Set<String> visiting,
294:            Set<String> visited) {
295:        if (visited.contains(roleId)) {
296:            return;
297:        }
298:        if (!visiting.add(roleId)) {
299:            throw new IllegalArgumentException("role inheritance cycle at " + roleId);
300:        }
301:        List<String> parents = new ArrayList<>(roles.get(roleId).parents);
302:        parents.sort(Comparator.naturalOrder());
303:        for (String parent : parents) {
304:            visit(parent, roles, visiting, visited);
305:        }
306:        visiting.remove(roleId);
307:        visited.add(roleId);
308:    }
309:
310:    private static Set<String> immutableSet(Collection<String> values) {
311:        return Collections.unmodifiableSet(
312:                new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
313:    }
314:
315:    private static String require(String value, String name) {
316:        Objects.requireNonNull(value, name);
317:        if (value.trim().isEmpty()) {
318:            throw new IllegalArgumentException(name + " must not be empty");
319:        }
320:        return value;
321:    }
322:}
