29:/** Owns session concurrency, expiry, zone transfer, and lifecycle notifications. */
30:public final class SessionSupervisor {
31:    public enum State {
32:        ACTIVE,
33:        IDLE,
34:        SUSPENDED,
35:        REAUTHENTICATION_REQUIRED,
36:        REVOKED,
37:        EXPIRED
38:    }
39:
40:    public enum EventType {
41:        OPENED,
42:        TOUCHED,
43:        TRANSFERRED,
44:        SUSPENDED,
45:        REAUTHENTICATION_REQUESTED,
46:        REVOKED,
47:        EXPIRED
48:    }
49:
50:    public interface Observer {
51:        void onEvent(Event event);
52:    }
53:
54:    public static final class Limits {
55:        public final int maximumPerAccount;
56:        public final int maximumPerZone;
57:        public final long idleTimeoutMillis;
58:        public final long absoluteTimeoutMillis;
59:        public final long reauthenticationWindowMillis;
60:
61:        public Limits(
62:                int maximumPerAccount,
63:                int maximumPerZone,
64:                long idleTimeoutMillis,
65:                long absoluteTimeoutMillis,
66:                long reauthenticationWindowMillis) {
67:            this.maximumPerAccount = maximumPerAccount;
68:            this.maximumPerZone = maximumPerZone;
69:            this.idleTimeoutMillis = idleTimeoutMillis;
70:            this.absoluteTimeoutMillis = absoluteTimeoutMillis;
71:            this.reauthenticationWindowMillis = reauthenticationWindowMillis;
72:            if (maximumPerAccount <= 0 || maximumPerZone <= 0) {
73:                throw new IllegalArgumentException("session maxima must be positive");
74:            }
75:            if (idleTimeoutMillis <= 0 || absoluteTimeoutMillis <= idleTimeoutMillis) {
76:                throw new IllegalArgumentException("invalid session timeouts");
77:            }
78:            if (reauthenticationWindowMillis <= 0) {
79:                throw new IllegalArgumentException("reauthentication window must be positive");
80:            }
81:        }
82:    }
83:
84:    public static final class Session {
85:        public final String id;
86:        public final String accountId;
87:        public final int userId;
88:        private String zone;
89:        private State state;
90:        private final long openedAt;
91:        private long lastActiveAt;
92:        private long authenticatedAt;
93:        private String reason;
94:
95:        Session(
96:                String id,
97:                String accountId,
98:                int userId,
99:                String zone,
100:                long now) {
101:            this.id = require(id, "id");
102:            this.accountId = require(accountId, "accountId");
103:            this.userId = userId;
104:            this.zone = require(zone, "zone");
105:            this.state = State.ACTIVE;
106:            this.openedAt = now;
107:            this.lastActiveAt = now;
108:            this.authenticatedAt = now;
109:            this.reason = "";
110:        }
111:
112:        public synchronized String zone() {
113:            return zone;
114:        }
115:
116:        public synchronized State state() {
117:            return state;
118:        }
119:
120:        public synchronized long openedAt() {
121:            return openedAt;
122:        }
123:
124:        public synchronized long lastActiveAt() {
125:            return lastActiveAt;
126:        }
127:
128:        public synchronized String reason() {
129:            return reason;
130:        }
131:    }
132:
133:    public static final class Event {
134:        public final EventType type;
135:        public final String sessionId;
136:        public final String accountId;
137:        public final String zone;
138:        public final String reason;
139:        public final long timestamp;
140:
141:        Event(
142:                EventType type,
143:                Session session,
144:                String reason,
145:                long timestamp) {
146:            this.type = type;
147:            this.sessionId = session.id;
148:            this.accountId = session.accountId;
149:            this.zone = session.zone;
150:            this.reason = reason;
151:            this.timestamp = timestamp;
152:        }
153:    }
154:
155:    private final Limits limits;
156:    private final Map<String, Session> sessions = new LinkedHashMap<>();
157:    private final List<Observer> observers = new ArrayList<>();
158:
159:    public SessionSupervisor(Limits limits) {
160:        this.limits = Objects.requireNonNull(limits, "limits");
161:    }
162:
163:    public synchronized void addObserver(Observer observer) {
164:        observers.add(Objects.requireNonNull(observer, "observer"));
165:    }
166:
167:    public synchronized void removeObserver(Observer observer) {
168:        observers.remove(observer);
169:    }
170:
171:    public synchronized Session open(
172:            String sessionId,
173:            String accountId,
174:            int userId,
175:            String zone,
176:            long now) {
177:        if (sessions.containsKey(sessionId)) {
178:            throw new IllegalArgumentException("duplicate session: " + sessionId);
179:        }
180:        expire(now);
181:        enforceCapacity(accountId, zone);
182:        Session session = new Session(sessionId, accountId, userId, zone, now);
183:        sessions.put(sessionId, session);
184:        publish(EventType.OPENED, session, "", now);
185:        return session;
186:    }
187:
188:    public synchronized void touch(String sessionId, long now) {
189:        Session session = requireActive(sessionId);
190:        synchronized (session) {
191:            if (now < session.lastActiveAt) {
192:                throw new IllegalArgumentException("activity time moved backwards");
193:            }
194:            session.lastActiveAt = now;
195:            if (session.state == State.IDLE) {
196:                session.state = State.ACTIVE;
197:            }
198:        }
199:        publish(EventType.TOUCHED, session, "", now);
200:    }
201:
202:    public synchronized void transfer(String sessionId, String targetZone, long now) {
203:        Session session = requireActive(sessionId);
204:        String normalized = require(targetZone, "targetZone");
205:        if (!session.zone.equals(normalized)) {
206:            enforceZoneCapacity(normalized);
207:            synchronized (session) {
208:                session.zone = normalized;
209:                session.lastActiveAt = now;
210:            }
211:            publish(EventType.TRANSFERRED, session, "zone transfer", now);
212:        }
213:    }
214:
215:    public synchronized void suspend(String sessionId, String reason, long now) {
216:        Session session = requireActive(sessionId);
217:        transition(session, State.SUSPENDED, require(reason, "reason"));
218:        publish(EventType.SUSPENDED, session, reason, now);
219:    }
220:
221:    public synchronized void requireReauthentication(
222:            String sessionId,
223:            String reason,
224:            long now) {
225:        Session session = requireActive(sessionId);
226:        transition(session, State.REAUTHENTICATION_REQUIRED, require(reason, "reason"));
227:        publish(EventType.REAUTHENTICATION_REQUESTED, session, reason, now);
228:    }
229:
230:    public synchronized void reauthenticated(String sessionId, long now) {
231:        Session session = requireExisting(sessionId);
232:        synchronized (session) {
233:            if (session.state != State.REAUTHENTICATION_REQUIRED
234:                    && session.state != State.SUSPENDED) {
235:                throw new IllegalStateException("session did not require reauthentication");
236:            }
237:            session.state = State.ACTIVE;
238:            session.authenticatedAt = now;
239:            session.lastActiveAt = now;
240:            session.reason = "";
241:        }
242:        publish(EventType.TOUCHED, session, "reauthenticated", now);
243:    }
244:
245:    public synchronized void revoke(String sessionId, String reason, long now) {
246:        Session session = requireExisting(sessionId);
247:        transition(session, State.REVOKED, require(reason, "reason"));
248:        publish(EventType.REVOKED, session, reason, now);
249:    }
250:
251:    public synchronized int expire(long now) {
252:        int expired = 0;
253:        for (Session session : sessions.values()) {
254:            synchronized (session) {
255:                if (terminal(session.state)) {
256:                    continue;
257:                }
258:                boolean absolute = now - session.openedAt >= limits.absoluteTimeoutMillis;
259:                boolean idle = now - session.lastActiveAt >= limits.idleTimeoutMillis;
260:                boolean staleAuthentication = session.state == State.REAUTHENTICATION_REQUIRED
261:                        && now - session.authenticatedAt >= limits.reauthenticationWindowMillis;
262:                if (absolute || idle || staleAuthentication) {
263:                    session.state = State.EXPIRED;
264:                    session.reason = absolute
265:                            ? "absolute timeout"
266:                            : staleAuthentication ? "reauthentication timeout" : "idle timeout";
267:                    publish(EventType.EXPIRED, session, session.reason, now);
268:                    expired++;
269:                } else if (now - session.lastActiveAt >= limits.idleTimeoutMillis / 2
270:                        && session.state == State.ACTIVE) {
271:                    session.state = State.IDLE;
272:                }
273:            }
274:        }
275:        return expired;
276:    }
277:
278:    public synchronized int removeTerminal() {
279:        int removed = 0;
280:        Iterator<Session> iterator = sessions.values().iterator();
281:        while (iterator.hasNext()) {
282:            if (terminal(iterator.next().state)) {
283:                iterator.remove();
284:                removed++;
285:            }
286:        }
287:        return removed;
288:    }
289:
290:    public synchronized List<Session> snapshot() {
291:        List<Session> values = new ArrayList<>(sessions.values());
292:        values.sort(Comparator.comparing((Session value) -> value.accountId)
293:                .thenComparing(value -> value.zone)
294:                .thenComparing(value -> value.id));
295:        return Collections.unmodifiableList(values);
296:    }
297:
298:    private void enforceCapacity(String accountId, String zone) {
299:        int accountCount = 0;
300:        for (Session session : sessions.values()) {
301:            if (!terminal(session.state) && session.accountId.equals(accountId)) {
302:                accountCount++;
303:            }
304:        }
305:        if (accountCount >= limits.maximumPerAccount) {
306:            throw new IllegalStateException("account session capacity reached");
307:        }
308:        enforceZoneCapacity(zone);
309:    }
310:
311:    private void enforceZoneCapacity(String zone) {
312:        int zoneCount = 0;
313:        for (Session session : sessions.values()) {
314:            if (!terminal(session.state) && session.zone.equals(zone)) {
315:                zoneCount++;
316:            }
317:        }
318:        if (zoneCount >= limits.maximumPerZone) {
319:            throw new IllegalStateException("zone session capacity reached");
320:        }
321:    }
322:
323:    private Session requireActive(String sessionId) {
324:        Session session = requireExisting(sessionId);
325:        if (terminal(session.state)) {
326:            throw new IllegalStateException("session is terminal");
327:        }
328:        return session;
329:    }
330:
331:    private Session requireExisting(String sessionId) {
332:        Session session = sessions.get(sessionId);
333:        if (session == null) {
334:            throw new IllegalArgumentException("unknown session: " + sessionId);
335:        }
336:        return session;
337:    }
338:
339:    private static void transition(Session session, State state, String reason) {
340:        synchronized (session) {
341:            session.state = state;
342:            session.reason = reason;
343:        }
344:    }
345:
346:    private void publish(EventType type, Session session, String reason, long timestamp) {
347:        Event event = new Event(type, session, reason, timestamp);
348:        for (Observer observer : new ArrayList<>(observers)) {
349:            observer.onEvent(event);
350:        }
351:    }
352:
353:    private static boolean terminal(State state) {
354:        return state == State.REVOKED || state == State.EXPIRED;
355:    }
356:
357:    private static String require(String value, String name) {
358:        Objects.requireNonNull(value, name);
359:        if (value.trim().isEmpty()) {
360:            throw new IllegalArgumentException(name + " must not be empty");
361:        }
362:        return value;
363:    }
364:}
